import Link from 'next/link'

export default function Forbidden() {
  return (
    <main
      style={{
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        justifyContent: 'center',
        minHeight: '100vh',
        fontFamily: 'system-ui, sans-serif',
        textAlign: 'center',
        padding: '2rem',
      }}
    >
      <h1
        style={{
          fontSize: '4rem',
          fontWeight: 'bold',
          margin: '0 0 1rem 0',
          color: '#dc2626',
        }}
      >
        403
      </h1>
      <h2
        style={{
          fontSize: '1.5rem',
          fontWeight: 'semibold',
          margin: '0 0 1rem 0',
          color: '#374151',
        }}
      >
        Access Forbidden
      </h2>
      <p
        style={{
          fontSize: '1rem',
          color: '#6b7280',
          margin: '0 0 2rem 0',
          maxWidth: '400px',
        }}
      >
        You do not have permission to access this page. Please contact an
        administrator if you believe this is an error.
      </p>
      <Link
        href="/"
        style={{
          padding: '0.75rem 1.5rem',
          backgroundColor: '#2563eb',
          color: 'white',
          borderRadius: '0.375rem',
          textDecoration: 'none',
          fontWeight: 'medium',
        }}
      >
        Return to Home
      </Link>
    </main>
  )
}

